export const flowBanner = (k, txt, link = '') => `<div class="f-flow-banner">${icon('route', 'ico')}<span><b>${t(`Flow ${k}`, `ফ্লো ${k}`)}</b> · ${txt}</span>${link}</div>`;

// ---------- division map (Variation H) ----------
function centroid(dp) { const v = dp.match(/-?\d+(\.\d+)?/g).map(Number); let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9; for (let i = 0; i < v.length; i += 2) { x0 = Math.min(x0, v[i]); x1 = Math.max(x1, v[i]); y0 = Math.min(y0, v[i + 1]); y1 = Math.max(y1, v[i + 1]); } return [(x0 + x1) / 2, (y0 + y1) / 2]; }
const NUDGE = { chattogram: [-20, -60], khulna: [0, -30], dhaka: [-8, 10], mymensingh: [0, 8], rajshahi: [10, 0], rangpur: [0, 10] };
export function divisionMap(sel = 'chattogram') {
  const fill = (v) => (v.att < 80 ? '#C7685E' : v.att < 85 ? '#7FB3B0' : 'var(--teal-700)');
  return `<svg class="h-map" viewBox="${MAP.viewBox}" role="group" ${ta('aria-label', 'Attendance today by division', 'বিভাগভিত্তিক আজকের উপস্থিতি')}>${each(MAP.divisions, (m) => {
    const v = DIVISIONS.find((x) => x.id === m.id); const [cx, cy] = centroid(m.d); const [nx, ny] = NUDGE[m.id] || [0, 0]; const val = `${v.att.toFixed(1)}%`;
    return `<g class="h-map-div" data-map-div="${m.id}" tabindex="0" role="button" aria-pressed="${m.id === sel}" aria-label="${esc(v.n[0])}: ${val}"><path d="${m.d}" style="fill:${fill(v)}"/>
      <text x="${cx + nx}" y="${cy + ny}" class="h-map-name"><tspan class="l-en">${esc(v.n[0])}</tspan><tspan class="l-bn">${esc(v.n[1])}</tspan></text>
      <text x="${cx + nx}" y="${cy + ny + 24}" class="h-map-val"><tspan class="l-en">${val}</tspan><tspan class="l-bn">${bnDigits(val)}</tspan></text></g>`;
  })}</svg>`;
}
export const divJson = () => `<script type="application/json" id="div-data">${JSON.stringify(Object.fromEntries(DIVISIONS.map((v) => [v.id, { name: v.n, inst: v.inst, students: v.students, attTxt: `${v.att.toFixed(1)}%`, att: v.att, rep: v.rep, alerts: v.alerts, status: v.att < 80 ? ['Below the 80% threshold', '৮০% সীমার নিচে'] : ['Within target', 'লক্ষ্যমাত্রার মধ্যে'] }])))}</script>`;

export const noticeMini = (list) => `<ul class="h-nlist">${each(list, (x) => `<li><a href="notice-detail.html"><time>${d(x.date.slice(0, 6))}</time><span>${tt(x.t)}</span></a></li>`)}</ul>`;
