// ================= APPROVALS =================
function approvals() {
  const pr = { attrs: 'data-when="proc=submitted|approved|po|lc|received|gatepass"', status: 'pending', cells: ['<span class="mono">PR-2026-071</span>', `<b>${t('Procurement: 6 sewing machines', 'ক্রয়: ৬টি সেলাই মেশিন')}</b><small>${t('Karnaphuli TI · ৳ 4.8 lakh · import with LC', 'কর্ণফুলী টিআই · ৳ ৪.৮ লাখ · এলসির মাধ্যমে আমদানি')}</small>`, t('District Admin (forwarded)', 'জেলা অ্যাডমিন (প্রেরিত)'), n(0),
    `${when('proc=submitted', st('pending'), 'span')}${when('proc=approved|po|lc|received|gatepass', st('approved'), 'span')}`,
    when('proc=submitted', `<span class="f-acts"><button type="button" class="btn btn-teal btn-sm" ${act({ set: 'proc=approved', confirm: ['Approve PR-2026-071?', 'PR-2026-071 অনুমোদন করবেন?'], ctext: ['The institution can then issue the purchase order.', 'এরপর প্রতিষ্ঠান ক্রয়াদেশ ইস্যু করতে পারবে।'], toast: ['Procurement approved. The institution is notified.', 'ক্রয় অনুমোদিত। প্রতিষ্ঠানকে জানানো হয়েছে।'] })}>${t('Approve', 'অনুমোদন')}</button><button type="button" class="btn btn-outline btn-sm" ${act({ set: '_=1', confirm: ['Return PR-2026-071?', 'PR-2026-071 ফেরত পাঠাবেন?'], reason: true, toast: ['Returned with your note.', 'আপনার মন্তব্যসহ ফেরত পাঠানো হয়েছে।'] })}>${t('Return', 'ফেরত')}</button></span>`, 'span')] };
  const rows = [pr, ...MIN.approvals.map((x) => ({ status: x.overdue ? 'overdue' : 'pending', cells: [`<span class="mono">${x.ref}</span>`, `<b>${tt(x.t)}</b><small>${tt(x.type)} · ${tt(x.where)}</small>`, tt(x.from), `<span class="${x.overdue ? 'h-urgent' : ''}">${n(x.age)}</span><small>SLA ${n(x.sla)}</small>`, x.overdue ? st('overdue') : st('pending'),
    `<span class="f-acts"><button type="button" class="btn btn-teal btn-sm" ${act({ set: '_=1', confirm: [`Approve ${x.ref}?`, `${x.ref} অনুমোদন করবেন?`], toast: ['Approved. The requester is notified.', 'অনুমোদিত। অনুরোধকারীকে জানানো হয়েছে।'] })}>${t('Approve', 'অনুমোদন')}</button><button type="button" class="btn btn-outline btn-sm" ${act({ set: '_=1', confirm: [`Return ${x.ref}?`, `${x.ref} ফেরত পাঠাবেন?`], reason: true, toast: ['Returned with your note.', 'আপনার মন্তব্যসহ ফেরত পাঠানো হয়েছে।'] })}>${t('Return', 'ফেরত')}</button></span>`] }))];
  const body = `${pageHead({ title: t('Approvals and escalations', 'অনুমোদন ও উত্থাপিত বিষয়'), sub: t('Requests that need a Ministry decision. Lower-level approvals happen in the respective portals.', 'যেসব অনুরোধে মন্ত্রণালয়ের সিদ্ধান্ত প্রয়োজন। নিম্ন স্তরের অনুমোদন সংশ্লিষ্ট পোর্টালে হয়।') })}
  ${when('proc=none', alert('info', t('Flow G: no procurement request is waiting yet.', 'ফ্লো জি: এখনও কোনো ক্রয় অনুরোধ অপেক্ষমাণ নেই।'), t('Create one in the Institution Portal to see it here.', 'এখানে দেখতে প্রতিষ্ঠান পোর্টালে একটি তৈরি করুন।'), a('inst-procurement.html', t('Open institution procurement', 'প্রতিষ্ঠানের ক্রয় খুলুন'), 'btn btn-outline btn-sm')))}
  ${when('proc=approved|po|lc|received|gatepass', flowBanner('G', t('PR-2026-071 approved. The institution continues with the purchase order.', 'PR-2026-071 অনুমোদিত। প্রতিষ্ঠান ক্রয়াদেশ নিয়ে এগোবে।'), a('inst-procurement.html', t('Institution view', 'প্রতিষ্ঠানের দৃশ্য'), 'btn btn-outline btn-sm')))}
  ${table({ id: 'appr', search: ['Reference, institution or type', 'স্মারক, প্রতিষ্ঠান বা ধরন'], statusFilter: ['pending', 'overdue'], cols: [{ l: ['Ref.', 'স্মারক'] }, { l: ['Request', 'অনুরোধ'] }, { l: ['From', 'প্রেরক'] }, { l: ['Days', 'দিন'], cls: 'num' }, { l: ['Status', 'অবস্থা'] }, { l: ['Action', 'কাজ'] }], rows, foot: pager(5, 12) })}
  <p class="f-chart-meta">${t('Approval chains and thresholds for procurement, LC and gate pass', 'ক্রয়, এলসি ও গেট পাসের অনুমোদন ধাপ ও সীমা')} — ${tbd()}</p>`;
  return P('ministry-approvals', ['Approvals', 'অনুমোদন'], [['Approvals', 'অনুমোদন']], body);
}

